def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    lr=[i for i in range(h) if all(x!=bg for x in grid[i])]
    lc=[j for j in range(w) if all(grid[i][j]!=bg for i in range(h))]
    if not lr or not lc: return [[bg]]
    inter=[[grid[i][j] for j in lc] for i in lr]
    line=Counter(x for r_ in inter for x in r_).most_common(1)[0][0]
    H,W=len(inter),len(inter[0])
    lab=[[-1]*W for _ in range(H)]; rects={}
    from collections import deque
    for i in range(H):
        for j in range(W):
            if lab[i][j]==-1:
                v=inter[i][j]; lid=len(rects); q=deque([(i,j)]); lab[i][j]=lid; cells=[(i,j)]
                while q:
                    a,b=q.popleft()
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and lab[na][nb]==-1 and inter[na][nb]==v:
                            lab[na][nb]=lid; q.append((na,nb)); cells.append((na,nb))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                rects[lid]=(v,min(rs),min(cs),max(rs)-min(rs)+1,max(cs)-min(cs)+1)
    res=[[bg]*W for _ in range(H)]
    for v,r0,c0,rh,rw in rects.values():
        if v in (bg,line): continue
        kh,kw=math.ceil(rh/2),math.ceil(rw/2)
        for a in range(kh):
            for b in range(kw):
                res[r0+a][c0+b]=v
    rows=[i for i in range(H) if any(x!=bg for x in res[i])]
    cols=[j for j in range(W) if any(res[i][j]!=bg for i in range(H))]
    if not rows or not cols: return [[bg]]
    return [[res[i][j] for j in range(cols[0],cols[-1]+1)] for i in range(rows[0],rows[-1]+1)]

